CREATE TABLE IF NOT EXISTS wallets (address TEXT PRIMARY KEY, chain TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bots (id TEXT PRIMARY KEY, wallet TEXT NOT NULL REFERENCES wallets(address), asset TEXT NOT NULL, strategy TEXT NOT NULL, params JSONB NOT NULL DEFAULT '{}', risk JSONB NOT NULL, venue TEXT NOT NULL DEFAULT 'onchain-dex', state TEXT NOT NULL DEFAULT 'idle', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS intents (id TEXT PRIMARY KEY, bot_id TEXT REFERENCES bots(id), wallet TEXT NOT NULL, asset TEXT NOT NULL, chain TEXT NOT NULL, side TEXT NOT NULL, strategy TEXT NOT NULL, venue TEXT NOT NULL, notional_usd NUMERIC NOT NULL, qty NUMERIC NOT NULL, limit_price NUMERIC NOT NULL, max_slippage_bps INTEGER NOT NULL, deadline_ts BIGINT NOT NULL, client_order_id TEXT NOT NULL UNIQUE, state TEXT NOT NULL, fee_usd NUMERIC NOT NULL DEFAULT 0, expected_out NUMERIC NOT NULL, min_out NUMERIC NOT NULL, route_summary TEXT NOT NULL, payload JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS txs (hash TEXT PRIMARY KEY, chain TEXT NOT NULL, intent_id TEXT NOT NULL REFERENCES intents(id), wallet TEXT NOT NULL, to_addr TEXT NOT NULL, state TEXT NOT NULL, block_number BIGINT, confirmations INTEGER NOT NULL DEFAULT 0, finalized BOOLEAN NOT NULL DEFAULT FALSE, human_summary TEXT NOT NULL, submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id BIGSERIAL PRIMARY KEY, at TIMESTAMPTZ NOT NULL DEFAULT now(), actor TEXT NOT NULL, action TEXT NOT NULL, entity TEXT, payload JSONB NOT NULL DEFAULT '{}', ip TEXT);
CREATE TABLE IF NOT EXISTS app_flags (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO app_flags (key, value) VALUES ('emergency_pause', 'false') ON CONFLICT (key) DO NOTHING;
